package dev.diamondtier;

import net.minecraft.client.gui.GuiGraphics;

/** The DiamondTier hammer badge, stored as 48x48 pixels so it stays sharp. */
public final class HammerIcon {
    private static final int N = 48;
    private static final int[] PX = new int[N * N];

    static {
        String hex = "";
        for (int i = 0; i < PX.length; i++) PX[i] = (int) Long.parseLong(hex.substring(i * 8, i * 8 + 8), 16);
    }

    private HammerIcon() {}

    /** Draws the hammer with its top-left corner at (x, y), size x size units. */
    public static void draw(GuiGraphics g, float x, float y, float size) {
        g.pose().pushMatrix();
        g.pose().translate(x, y);
        float s = size / N;
        g.pose().scale(s, s);
        for (int row = 0; row < N; row++) {
            int col = 0;
            while (col < N) {
                int c = PX[row * N + col];
                if ((c >>> 24) == 0) { col++; continue; }
                int end = col + 1;
                while (end < N && PX[row * N + end] == c) end++;
                g.fill(col, row, end, row + 1, c);
                col = end;
            }
        }
        g.pose().popMatrix();
    }
}
